"""Common functions and low level user interaction functions for the main buttons pane in the SimDialogs test tool app.
Used by the SimDialogs page object class"""

from .objects.sim_dialogs_objects import SimDialogsObjects
from interops.libraries.squish_actions import CommonActions
from interops.libraries.miscellaneous import remote_py_functions
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import SIMDIALOGS_APP_NAME


def find_main_sim_dialogs_window():
    """Searches for the main Sim Dialogs window. Returns True if successfully located.

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(SimDialogsObjects.main_Sim_Dialogs_Window) is not None else False

def __restore_sim_dialog_window() -> bool:
    """Restores the minimized Sim Dialogs window using the win32 API in the ctypes library to get the
    window object handle from the window title and sets the window state using the ShowWindow() control
    parameter.

    ShowWindow() window control parameters. Refer to Windows win32 API for more info:
    https://docs.microsoft.com/en-us/windows/win32/api/winuser/nf-winuser-showwindow

    This function is intended to be used by execute_remote_py_function() in miscellaneous.py.
    execute_remote_py_function() uploads a temporary copy of this function on to the target system and
    executes the function on the remote system using the RemoteSystem library from the Squish API.

    -> Hidden function that should not be used outside the context of the sim_dialog_functions.py file

    :return: True or False
    :rtype: bool
    """

    # Library import is included in function definition as function is copied to remote system
    from ctypes import windll
    import logging

    # Setup logging on remote system
    logging_level = logging.INFO
    log_path_file = 'C://Temp//restore_sim_dialogs_app.log'
    FORMAT = "[%(asctime)s - %(levelname)s] - [%(filename)s:%(lineno)s %(funcName)s()] -  %(message)s"
    DATE_FORMAT='%m/%d/%Y %I:%M:%S %p'
    logging.basicConfig(filename=log_path_file,level=logging_level, format=FORMAT, datefmt=DATE_FORMAT)
    logging.info("restore_sim_dialog_window(): Entered...")

    try:
        # Control parameter to restore window using ShowWindow()
        SW_RESTORE = 9

        sim_dialogs_window_title = "Sim Dialogs"
        sim_dialogs_window_handle = windll.user32.FindWindowW(None, sim_dialogs_window_title)

        if sim_dialogs_window_handle:
            logging.info("restore_sim_dialog_window(): Found Sim Dialogs window handle")
            windll.user32.ShowWindow(sim_dialogs_window_handle, SW_RESTORE)
            logging.info("restore_sim_dialog_window(): Restored Sim Dialogs window")
            windll.user32.SetForegroundWindow(sim_dialogs_window_handle)
            logging.info("restore_sim_dialog_window(): Set Sim Dialogs window to foreground")
            return True
        return False

    except Exception as e:
        logging.exception("restore_sim_dialog_window(): Error obtaining Sim Dialogs window handle: " + str(e))
        return False

def locate_checkbox_per_pane_by_index_and_id(childObjIndex: int, checkBoxId: str) -> object:
    """Searches Sim Dialog pane child objects based on the positional index and finds the checkbox within
    the list of child objects based on the id. Returns object if successfully located. Assumes that the
    ordering of the child objects remains constant.

    Used for checkboxes that don't have a unique object property, but can be identified by drilling down
    the Sim Dialogs object tree and narrowing the search within a specific pane. The checkbox IDs are
    not unique in the main window but typically are within a specific pane.

    :param int childObjIndex: Index of the WindowsControl child object in the first level down to be searched
    :param str checkBoxId: Checkbox ID text string to be found
    :return: found object
    :rtype: object
    """
    if find_main_sim_dialogs_window():
        sim_dialogs_obj_list = CommonActions.get_child_objects(SimDialogsObjects.main_Sim_Dialogs_Window)

        if len(sim_dialogs_obj_list) > 0:
            pane_obj_list = sim_dialogs_obj_list[childObjIndex]

            child_pane_obj_list = CommonActions.get_child_objects(pane_obj_list)
            if len(child_pane_obj_list) > 0:
                checkbox_object = CommonActions.get_child_object_by_object_id(child_pane_obj_list, checkBoxId)
                return checkbox_object

@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def restore_sim_dialog_window_using_toplevelwindow() -> None:
    """Restores the minimized Sim Dialogs window using Squish's ToplevelWindow class.
    """
    top_sim_dialog_window = CommonActions.get_top_level_window_by_object(SimDialogsObjects.main_Sim_Dialogs_Window)
    top_sim_dialog_window.setFocus()
    top_sim_dialog_window.restore()

@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def minimise_sim_dialog_window_using_toplevelwindow() -> None:
    """Minimises the Sim Dialogs window using Squish's ToplevelWindow class.
    """
    top_sim_dialog_window = CommonActions.get_top_level_window_by_object(SimDialogsObjects.main_Sim_Dialogs_Window)
    top_sim_dialog_window.minimize()

def restore_sim_dialog_window_on_remote_system() -> bool:
    """An alternate method for restoring the minimized Sim Dialogs window on a remote system by invoking the
    execute_remote_py_function() from the remote_py_functions module. The __restore_sim_dialog_window()
    function is passed in as the first argument, and an empty list is passed in as the second argument as
    __restore_sim_dialog_window() has no arguments.

    A temporary copy of the __restore_sim_dialog_window() function is uploaded on to the target system and
    is this function is executed on the remote system using the RemoteSystem library from the Squish API.

    :return: True or False
    :rtype: bool
    """
    result = remote_py_functions.execute_remote_py_function(__restore_sim_dialog_window, [])

    if result is not None:
        return result
    return False

#-------------------------------------- Main Start, Stop and ASU buttons Pane --------------------------------------

@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def click_main_sim_dialogs_start_button() -> None:
    """Locates the main Sim Dialogs window > then left mouse click on the main Start button only if its enabled
    """
    if find_main_sim_dialogs_window():
        CommonActions.left_click_object_no_move(SimDialogsObjects.main_Start_Button)

@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def click_main_sim_dialogs_stop_button() -> None:
    """Locates the main Sim Dialogs window > then left mouse click on the main Stop button only if its enabled
    """
    if find_main_sim_dialogs_window():
        CommonActions.left_click_object_no_move(SimDialogsObjects.main_Stop_Button)

@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def click_main_sim_dialogs_asu_button() -> None:
    """Locates the main Sim Dialogs window > then left mouse click on the main ASU button only if its enabled
    """
    if find_main_sim_dialogs_window():
        CommonActions.left_click_object_no_move(SimDialogsObjects.main_ASU_Button)
